export const dataCapabilities=[['SOURCE SYSTEMS','ERP / CRM / POS / Files / Applications','The information already existed.'],['INGESTION & INTEGRATION','Connect the sources','Bring the relevant records into a usable flow.'],['DATA QUALITY & TRANSFORMATION','Prepare the information','Check records, align identifiers and normalize representations.'],['DATA PLATFORM / DATA WAREHOUSE','Organize business context','Maintain analytical data and relationships for reuse.'],['ANALYTICS','Answer and investigate','Compare results, follow evidence and state what is unknown.'],['AI / ML / GENERATIVE AI','Assist with a defined task','Predict or generate with suitable data, validation and controls.']];

