dataLessons.push(
 {name:'AI-Ready Data',what:'Relevant data that can support a defined AI task with known meaning, access and quality.',why:'A model cannot resolve an undefined business outcome or missing context by itself.',example:'Provide reviewed sales definitions and source evidence before requesting a management summary.',need:'“We want AI, but our data is not ready.”',connect:'Source ownership, preparation, governance and evaluation come before relying on AI output.',question:'Does putting data in one platform make it AI-ready?',answer:'No. Relevance, permissions, definitions, quality and evaluation still need explicit work.'},
 {name:'BigQuery',what:'Google Cloud’s analytical data platform for organizing and querying business data.',why:'Business questions can require analysis across large or varied datasets.',example:'Analyze prepared revenue, product and customer records together.',need:'“We need reusable cross-system analysis.”',connect:'It can support the analytical-context layer; integration and preparation remain separate design responsibilities.',question:'Will it automatically reconcile all our systems?',answer:'No. Data mapping, quality rules, ownership, cost controls and access design still matter.'},
 {name:'Looker',what:'A business intelligence platform for modeled metrics, analysis and exploration.',why:'Teams need shared definitions when investigating business performance.',example:'Follow an agreed sales measure from total revenue to regional contribution.',need:'“Our dashboards disagree about the same number.”',connect:'Models and permissions connect prepared data to governed business analysis.',question:'Will installing it make every metric trusted?',answer:'No. Business owners must agree definitions, models and access rules.'},
 {name:'Vertex AI',what:'A platform for building and using machine-learning and AI applications.',why:'Some use cases need evaluated predictions or AI assistance beyond a historical report.',example:'Evaluate a churn model against a defined outcome and relevant historical data.',need:'“We want a prediction we can evaluate and operate.”',connect:'Uses appropriate data, model evaluation and application design; it is an optional layer in this story.',question:'Does this simulation run a live model?',answer:'No. All answers are prepared example content. Real models require design, validation and monitoring.'},
 {name:'Gemini',what:'Google’s family of generative AI models, used through specific products or application integrations.',why:'A team may need help summarizing or communicating evidence it has already prepared.',example:'Draft a management summary with explicit source context and unresolved questions.',need:'“Can management ask questions in natural language?”',connect:'Useful assistance depends on selected context, permissions and review; it does not replace integration or analytics.',question:'Does it automatically know all company data?',answer:'No. Access, grounding and product capabilities depend on the chosen implementation. Outputs can be wrong and need review.'}
);
export const dataLearningSafeguards={
 'Data Sources':'Do not assume access, completeness or that every source must be replaced.',
 'Data Integration':'Do not imply every connector is available or every integration is instant.',
 'Data Quality':'Do not guarantee perfect data or delete similar records without validating identity.',
 'Data Transformation':'Do not reduce preparation to renaming columns; meaning and rules must be agreed.',
 'Data Warehouse / Data Platform':'Do not confuse centralized storage with usable or trusted business context.',
 'Analytics / BI':'Do not describe association as causation or promise every new question is already answerable.',
 'Machine Learning':'Do not promise accurate predictions without validation and a defined outcome.',
 'Generative AI':'Do not claim generated language proves the underlying facts.',
 'Streaming / Real-Time':'Do not promise zero latency; agree the end-to-end freshness requirement.',
 'Data Governance':'Do not imply centralization automatically establishes permissions or ownership.'
};
export const dataLearningRelevance={
 'Data Sources':'When a business question needs an inventory of the systems and people holding the evidence.',
 'Data Integration':'When the same question repeatedly requires data from more than one source.',
 'Data Quality':'When missing, conflicting or duplicated information could change a decision.',
 'Data Transformation':'When formats, identifiers or definitions prevent like-for-like comparison.',
 'Data Warehouse / Data Platform':'When cross-system analysis needs reusable, maintained data rather than repeated exports.',
 'Analytics / BI':'When people need to investigate a business result, not only view a report.',
 'Machine Learning':'When a repeatable prediction has a defined outcome and suitable evaluation data.',
 'Generative AI':'When reviewed context needs to become a useful first draft or summary.',
 'Streaming / Real-Time':'When the required decision becomes less useful before the next scheduled batch.',
 'Data Governance':'When ownership, definitions, provenance or access are unclear.',
 'AI-Ready Data':'Before building an AI use case that depends on company-specific information.',
 'BigQuery':'When choosing a platform for prepared analytical data and cross-system queries.',
 'Looker':'When teams need modeled, agreed metrics and governed exploration.',
 'Vertex AI':'When a defined AI or ML use case needs implementation, evaluation and operation.',
 'Gemini':'When a selected workflow would benefit from generated content grounded in permitted context.'
};
